record Klient(int id, String imie, double saldo) { }

static void saveClients(File plik, List<Klient> clients) throws IOException {
    try (DataOutputStream dos = new DataOutputStream(new FileOutputStream(plik))) {
        dos.writeInt(clients.size());
        for (Klient k : clients) {
            dos.writeInt(k.id()); dos.writeUTF(k.imie()); dos.writeDouble(k.saldo());
        }
    }
}

static List<Klient> loadClients(File plik) throws IOException {
    List<Klient> result = new ArrayList<>();
    try (DataInputStream dis = new DataInputStream(new FileInputStream(plik))) {
        int count = dis.readInt();
        for (int i = 0; i < count; i++) {
            result.add(new Klient(dis.readInt(), dis.readUTF(), dis.readDouble()));
        }
    }
    return result;
}

File plik = new File(System.getProperty("java.io.tmpdir"), "klienci.bin");
List<Klient> clients = new ArrayList<>(List.of(
        new Klient(1, "Ala", 1000), new Klient(2, "Bartek", 2000)));
saveClients(plik, clients);
System.out.println("Po zapisie: " + loadClients(plik));

List<Klient> loaded = loadClients(plik);
loaded.add(new Klient(3, "Celina", 3000));
saveClients(plik, loaded);
System.out.println("Po dodaniu: " + loadClients(plik));

List<Klient> afterAdd = loadClients(plik);
List<Klient> filtered = afterAdd.stream().filter(k -> k.id() != 2).toList();
saveClients(plik, filtered);
System.out.println("Po usunieciu id=2: " + loadClients(plik));
plik.delete();

